19	// the test binds to the MEANING, not one capitalisation ("Paid"/"PAID"/"paid ✓" all count). The
20	// word boundary keeps "Unpaid"/"UNPAID" from matching, so the same regex distinguishes the two
21	// states without pinning the exact unpaid wording.
22	const PAID = /\bpaid\b/i;
23	
