25	const statusOf = (page: Page, id: number): Locator =>
26	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-status');
27	
28	// The audit record for one marking. The amount may be written bare (100) or with scale (100.00), so
29	// accept an optional fractional part; everything else is matched exactly.
30	const paidRecord = (id: number, amount: number) =>
31	  new RegExp(`^INVOICE_PAID id=${id} amount=${amount}(\\.\\d+)?$`);
32	
33	const paidRecordsFor = (id: number, amount: number): string[] =>
34	  auditLines().filter((line) => paidRecord(id, amount).test(line));
35	
36	test.describe('Mark an invoice as paid', () => {
37	  test('marking an unpaid invoice flips its status to paid, persists, and records it once', async ({
38	    page,
39	  }) => {
40	    await resetAndSeed({
41	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
42	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
43	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'UNPAID' }],
44	    });
45	
46	    await page.goto('/projects/1');
47	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
48	
49	    // The invoice starts out not paid, and offers a control to mark it paid.
50	    await expect(statusOf(page, 1)).not.toHaveText(PAID);
51	    const pay = page.getByTestId('invoice-pay-1');
