55	    // marking (not the seeding) wrote it.
56	    expect(auditLines()).toEqual([]);
57	
58	    await pay.click();
59	
60	    // The status now reads paid.
61	    await expect(statusOf(page, 1)).toHaveText(PAID);
62	
63	    // And exactly one record was kept for this marking, carrying the invoice's id and amount.
64	    expect(paidRecordsFor(1, 100)).toHaveLength(1);
65	    expect(auditLines()).toHaveLength(1);
66	
67	    // The paid status is held by the server, not just the page: it survives a fresh load, and
68	    // reloading does not record the marking a second time.
69	    await page.reload();
70	    await expect(statusOf(page, 1)).toHaveText(PAID);
71	    expect(paidRecordsFor(1, 100)).toHaveLength(1);
