1	// Acceptance test for the change request:
2	//   "I want to track the projects I do for clients. Let me add a project and pick which client it
3	//    is for. Show each project with the client's name."
4	//
5	// A project belongs to a client. The projects page lists every project, and each project is shown
6	// together with the NAME of the client it is for (not an id). A new project is added by giving it a
7	// name and PICKING which client it is for; once added it joins the same single list, carrying that
8	// client's name.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
11	// endpoint): `clients` honours { id, name, email } and `projects` honours { id, name, clientId }.
12	import { test, expect, type Page } from '@playwright/test';
13	import { resetAndSeed } from '../support/seed';
