16	
17	// Locate the one project row carrying the given name, regardless of its server-assigned id.
18	const projectRowNamed = (page: Page, name: string) =>
19	  projectRows(page).filter({
20	    has: page.getByTestId('project-name').getByText(name, { exact: true }),
21	  });
22	
23	test.describe('Projects', () => {
24	  test('a link in the nav opens the projects page', async ({ page }) => {
25	    await resetAndSeed({ clients: [], projects: [] });
26	
